--
-- Name: insert_otp(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insert_otp(p_phone text, p_purpose text, p_plain_otp text, p_validity_minutes integer DEFAULT 3) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_hash TEXT;
  v_id BIGINT;
BEGIN
  v_hash := crypt(p_plain_otp, gen_salt('bf')); -- bcrypt
  INSERT INTO otp_codes(phone, purpose, otp_hash, expires_at)
    VALUES (p_phone, p_purpose, v_hash, now() + (p_validity_minutes || ' minutes')::interval)
    RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION public.insert_otp(p_phone text, p_purpose text, p_plain_otp text, p_validity_minutes integer) OWNER TO postgres;

--
-- Name: verify_otp(text, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_otp(p_phone text, p_purpose text, p_plain_otp text, p_max_attempts integer DEFAULT 3) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  rec RECORD;
  v_attempts INT;
BEGIN
  -- Récupère le dernier OTP non consommé et le verrouille
  SELECT * INTO rec FROM otp_codes
    WHERE phone = p_phone AND purpose = p_purpose AND consumed = false
    ORDER BY created_at DESC
    LIMIT 1
    FOR UPDATE;

  IF NOT FOUND THEN
    RETURN json_build_object('status','not_found');
  END IF;

  IF rec.expires_at < now() THEN
    UPDATE otp_codes SET consumed = true WHERE id = rec.id;
    RETURN json_build_object('status','expired');
  END IF;

  -- Vérification du hash
  IF crypt(p_plain_otp, rec.otp_hash) = rec.otp_hash THEN
    UPDATE otp_codes SET consumed = true WHERE id = rec.id;
    RETURN json_build_object('status','verified');
  ELSE
    UPDATE otp_codes SET attempts = attempts + 1 WHERE id = rec.id RETURNING attempts INTO v_attempts;
    IF v_attempts >= p_max_attempts THEN
      UPDATE otp_codes SET consumed = true WHERE id = rec.id;
      RETURN json_build_object('status','locked','attempts', v_attempts);
    ELSE
      RETURN json_build_object('status','invalid','attempts', v_attempts);
    END IF;
  END IF;
END;
$$;


