--
-- Name: transactions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.transactions (
    id bigint NOT NULL,
    amount numeric(19,4) NOT NULL,
    authorization_method character varying(255),
    authorized_at timestamp(6) without time zone,
    completed_at timestamp(6) without time zone,
    created_at timestamp(6) without time zone NOT NULL,
    currency character varying(255) NOT NULL,
    description character varying(255),
    exchange_rate double precision,
    fee double precision,
    is_refunded boolean,
    is_reversed boolean,
    last_updated_at timestamp(6) without time zone,
    processed_at timestamp(6) without time zone,
    reference character varying(255) NOT NULL,
    status character varying(255) NOT NULL,
    type character varying(255) NOT NULL,
    receiver_wallet_id bigint NOT NULL,
    sender_wallet_id bigint NOT NULL,
    authorization_required boolean,
    cancelled_at timestamp(6) without time zone,
    channel character varying(255),
    compliance_status character varying(255),
    expired_at timestamp(6) without time zone,
    failed_at timestamp(6) without time zone,
    fee_amount numeric(19,4),
    fee_currency character varying(255),
    fee_type character varying(255),
    initiated_at timestamp(6) without time zone,
    initiated_by character varying(255),
    last_updated_by character varying(255),
    max_retry integer,
    metadata character varying(255),
    on_hold_at timestamp(6) without time zone,
    pending_at timestamp(6) without time zone,
    processing_at timestamp(6) without time zone,
    receiver_wallet_number character varying(255) NOT NULL,
    refunded_at timestamp(6) without time zone,
    retry_count integer,
    reversed_at timestamp(6) without time zone,
    risk_score integer,
    route character varying(255),
    scheduled boolean,
    scheduled_for timestamp(6) without time zone,
    sender_wallet_number character varying(255) NOT NULL,
    under_review_at timestamp(6) without time zone,
    actual_authorization_method character varying(50),
    phone_number_used_for_auth character varying(20),
    payment_method character varying(255),
    version bigint,
    authorization_level integer,
    device_info character varying(255),
    failure_reason character varying(255),
    ip_address character varying(45),
    related_transaction_id bigint,
    total_amount numeric(19,4),
    category character varying,
    transaction_reference character varying,
    user_id character varying,
    CONSTRAINT transactions_authorization_method_check CHECK (((authorization_method)::text = ANY ((ARRAY['PIN'::character varying, 'OTP'::character varying, 'BIOMETRIC'::character varying, 'TWO_FA'::character varying, 'ADMIN'::character varying])::text[]))),
    CONSTRAINT transactions_channel_check CHECK (((channel)::text = ANY ((ARRAY['WEB'::character varying, 'MOBILE'::character varying, 'API'::character varying, 'ATM'::character varying, 'AGENT'::character varying, 'POS'::character varying, 'QR_CODE'::character varying, 'CONTACTLESS'::character varying, 'SCHEDULED'::character varying, 'BATCH'::character varying])::text[]))),
    CONSTRAINT transactions_compliance_status_check CHECK (((compliance_status)::text = ANY ((ARRAY['CLEAR'::character varying, 'UNDER_REVIEW'::character varying, 'BLOCKED'::character varying])::text[]))),
    CONSTRAINT transactions_payment_method_check CHECK (((payment_method)::text = ANY ((ARRAY['WALLET'::character varying, 'BANK_TRANSFER'::character varying, 'CARD'::character varying, 'MOBILE_MONEY'::character varying, 'USSD'::character varying, 'QR_CODE'::character varying, 'CRYPTO'::character varying, 'CASH'::character varying, 'CHECK'::character varying, 'AGENT'::character varying, 'ATM'::character varying, 'POS'::character varying, 'AFFILIATE'::character varying, 'REFERRAL'::character varying])::text[]))),
    CONSTRAINT transactions_status_check CHECK (((status)::text = ANY ((ARRAY['INITIATED'::character varying, 'PENDING'::character varying, 'AUTHORIZED'::character varying, 'PROCESSING'::character varying, 'COMPLETED'::character varying, 'FAILED'::character varying, 'CANCELLED'::character varying, 'REVERSED'::character varying, 'REFUNDED'::character varying, 'EXPIRED'::character varying, 'ON_HOLD'::character varying, 'UNDER_REVIEW'::character varying])::text[]))),
    CONSTRAINT transactions_type_check CHECK (((type)::text = ANY ((ARRAY['INIT'::character varying, 'DEPOSIT'::character varying, 'WITHDRAW'::character varying, 'P2P_TRANSFER'::character varying])::text[])))
);


