    registration_date timestamp(6) without time zone,
    two_factor_enabled boolean,
    two_factor_secret character varying(100),
    updated_at timestamp(6) without time zone,
    wallet_id character varying(255),
    admin_level character varying(20),
    can_access_reports boolean,
    can_approve_transactions boolean,
    can_managekyc boolean,
    can_manage_roles boolean,
    can_manage_users boolean,
    can_view_audit_logs boolean,
    employee_id character varying(20),
    last_admin_action_at timestamp(6) without time zone,
    supervisor_id bigint,
    business_address character varying(500),
    business_name character varying(200),
    business_registration_number character varying(50),
    can_accept_payments boolean,
    commission_rate numeric(5,2),
    is_verified_merchant boolean,
    merchant_verified_at timestamp(6) without time zone,
    total_transaction_volume numeric(15,2),
    total_transactions integer,
    verified_by character varying(255),
    email_notifications_enabled boolean,
    kyc_submitted_at timestamp(6) without time zone,
    kyc_verified_at timestamp(6) without time zone,
    last_transaction_at timestamp(6) without time zone,
    marketing_emails_enabled boolean,
    notifications_enabled boolean,
    preferred_currency character varying(10),
    preferred_language character varying(10),
    profile_picture character varying(500),
    sms_notifications_enabled boolean,
    id bigint NOT NULL,
    role character varying(255),
    pin_changed_at timestamp(6) without time zone,
    registration_ip character varying,
    region_code character varying(100),
    CONSTRAINT users_account_status_check CHECK (((account_status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying, 'SUSPENDED'::character varying, 'FROZEN'::character varying, 'CLOSED'::character varying, 'PENDING_VERIFICATION'::character varying])::text[]))),
    CONSTRAINT users_admin_level_check CHECK (((admin_level)::text = ANY ((ARRAY['STANDARD'::character varying, 'SENIOR'::character varying, 'SUPER_ADMIN'::character varying])::text[]))),
    CONSTRAINT users_check CHECK ((((user_type)::text <> 'ADMIN'::text) OR ((email_verified IS NOT NULL) AND (can_view_audit_logs IS NOT NULL)))),
    CONSTRAINT users_check1 CHECK ((((user_type)::text <> 'MERCHANT'::text) OR (email_verified IS NOT NULL))),
    CONSTRAINT users_check2 CHECK ((((user_type)::text <> 'REGULAR_USER'::text) OR (email_verified IS NOT NULL))),
    CONSTRAINT users_region_code_check CHECK (((region_code)::text = ANY ((ARRAY['AD'::character varying, 'CE'::character varying, 'ES'::character varying, 'EN'::character varying, 'LT'::character varying, 'NO'::character varying, 'NW'::character varying, 'OU'::character varying, 'SU'::character varying, 'SW'::character varying])::text[]))),
    CONSTRAINT users_role_check CHECK (((role)::text = ANY ((ARRAY['USER'::character varying, 'ADMIN'::character varying])::text[]))),
    CONSTRAINT users_user_type_check CHECK (((user_type)::text = ANY ((ARRAY['ADMIN'::character varying, 'MERCHANT'::character varying, 'REGULAR_USER'::character varying])::text[])))
);


